const body = $input.first().json.body || $input.first().json;
const message = body.message || body.text || body.input || '';
const sessionId = body.session_id || 'default';
const domain = body.domain || null;

if (!message) {
  throw new Error('No message provided. Send { message: "your text", session_id: "optional" }');
}

return [{ json: { message, sessionId, domain, timestamp: new Date().toISOString() } }];

const raw = $input.first().json;
const content = raw.choices?.[0]?.message?.content || '{}';

let classification;
try {
  const cleaned = content.replace(/```json|```/g, '').trim();
  classification = JSON.parse(cleaned);
} catch (e) {
  classification = { domain: 'general', complexity: 'medium', task_type: 'other', one_liner: 'General request' };
}

const prev = $('Parse Input').first().json;

// Groq model routing:
// high complexity   -> llama-3.3-70b-versatile (smartest, still free tier)
// medium complexity -> llama-3.1-70b-versatile  (solid all-rounder)
// low complexity    -> llama-3.1-8b-instant      (fastest, cheapest)
const modelMap = {
  high:   'llama-3.3-70b-versatile',
  medium: 'llama-3.1-70b-versatile',
  low:    'llama-3.1-8b-instant'
};

const model = modelMap[classification.complexity] || 'llama-3.1-70b-versatile';

return [{
  json: {
    message: prev.message,
    sessionId: prev.sessionId,
    timestamp: prev.timestamp,
    domain: classification.domain,
    complexity: classification.complexity,
    task_type: classification.task_type,
    one_liner: classification.one_liner,
    model
  }
}];

const current = $('Build System Prompt').first().json;
const memoryRows = $input.all().map(r => r.json).filter(r => r.session_id);

const historyMessages = memoryRows
  .sort((a, b) => new Date(a.created_at) - new Date(b.created_at))
  .flatMap(row => [
    { role: 'user', content: row.user_message },
    { role: 'assistant', content: row.assistant_response }
  ])
  .filter(m => m.content);

const messages = [
  { role: 'system', content: current.systemPrompt },
  ...historyMessages,
  { role: 'user', content: current.message }
];

return [{ json: { ...current, messages } }];

const groqRes = $input.first().json;
const ctx = $('Build Message History').first().json;

const responseText = groqRes.choices?.[0]?.message?.content || 'No response generated.';
const modelUsed = groqRes.model || ctx.model;
const inputTokens = groqRes.usage?.prompt_tokens || 0;
const outputTokens = groqRes.usage?.completion_tokens || 0;

return [{
  json: {
    sessionId: ctx.sessionId,
    domain: ctx.domain,
    complexity: ctx.complexity,
    task_type: ctx.task_type,
    one_liner: ctx.one_liner,
    model_used: modelUsed,
    input_tokens: inputTokens,
    output_tokens: outputTokens,
    user_message: ctx.message,
    assistant_response: responseText,
    timestamp: ctx.timestamp
    tts_text: responseText.length > 500 ? responseText.slice(0, 497) + '...' : responseText,
  }
}];
